/// The extension IEs of `SupportedTAItem-ExtIEs` (NGAP-IEs). IEs not defined here are kept in `unknown_ies`.
#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct SupportedTaItemExtIes {
    /// `id-ConfiguredTACIndication` (id 272, Ignore, Optional)
    pub configured_tac_indication: Option<ConfiguredTacIndication>,
    /// `id-RAT-Information` (id 179, Reject, Optional)
    pub rat_information: Option<RatInformation>,
    /// IEs this version of the specification does not define here, as received (id, criticality, encoded value).
    pub unknown_ies: Vec<rt::ie::RawIe>,
}

impl SupportedTaItemExtIes {
    /// A value with the mandatory IEs given and every optional one absent.
    pub fn new() -> Self {
        Self {
            configured_tac_indication: None,
            rat_information: None,
            unknown_ies: Vec::new(),
        }
    }
}

impl rt::AperEncode for SupportedTaItemExtIes {
    fn aper_encode(&self, w: &mut rt::BitWriter) -> rt::Result<()> {
        let mut ies: Vec<rt::ie::RawIe> = Vec::new();
        if let Some(x) = &self.configured_tac_indication {
            ies.push(rt::ie::RawIe::new(272, rt::ie::Criticality::Ignore, x)?);
        }
        if let Some(x) = &self.rat_information {
            ies.push(rt::ie::RawIe::new(179, rt::ie::Criticality::Reject, x)?);
        }
        ies.extend(self.unknown_ies.iter().cloned());
        rt::ie::write_container(w, rt::Size::range(1, 65535), &ies)
    }
}

impl rt::AperDecode for SupportedTaItemExtIes {
    fn aper_decode(r: &mut rt::BitReader<'_>) -> rt::Result<Self> {
        let mut s_configured_tac_indication: Option<ConfiguredTacIndication> = None;
        let mut s_rat_information: Option<RatInformation> = None;
        let mut unknown_ies = Vec::new();
        for ie in rt::ie::read_container(r, rt::Size::range(1, 65535))? {
            match ie.id {
                272 => rt::ie::set_once(&mut s_configured_tac_indication, 272, ie.decode()?)?,
                179 => rt::ie::set_once(&mut s_rat_information, 179, ie.decode()?)?,
                _ => unknown_ies.push(ie),
            }
        }
        Ok(Self {
            configured_tac_indication: s_configured_tac_indication,
            rat_information: s_rat_information,
            unknown_ies,
        })
    }
}

